/**
 * VITALIS — shared domain types.
 *
 * These interfaces mirror the proposed frontend/backend contract (see
 * `src/services/contracts.ts`). Nothing here describes a real astronaut or a
 * real mission: every value rendered in the UI is generated by the local
 * simulation engine unless a live transport is configured.
 */

export type DataMode = 'demo' | 'live';
export type DemoScenario = 'normal' | 'suspected' | 'confirmed';
export type AnomalyStatus = 'normal' | 'suspected' | 'confirmed';
export type ChannelStatus = 'normal' | 'anomaly' | 'nodata';
export type Severity = 'info' | 'success' | 'warning' | 'critical';
export type SensorId = 'hr' | 'hrv' | 'spo2' | 'temp' | 'activity' | 'sleep';
export type WindowSeconds = 30 | 60 | 120 | 240;

export interface PhysiologicalBaseline {
  hr: number;
  hrv: number;
  spo2: number;
  temp: number;
  activity: number;
  sleep: number;
}

export interface Astronaut {
  id: string;
  profileId: string;
  name: string;
  callsign: string;
  rank: string;
  role: string;
  missionId: string;
  baselineWindows: number;
  baselineDays: number;
  baselineComplete: boolean;
  baseline: PhysiologicalBaseline;
  simulated: boolean;
}

export interface Mission {
  id: string;
  name: string;
  vehicle: string;
  phase: string;
  status: 'active' | 'standby';
  simulation: boolean;
  startedAt: string;
  metSeconds: number;
  orbit: string;
  groundStation: string;
}

export interface SensorReading {
  id: SensorId;
  label: string;
  shortLabel: string;
  unit: string;
  value: number;
  displayValue: string;
  precision: number;
  status: ChannelStatus;
  quality: number;
  updatedAt: number;
  trend: number[];
  normalRange: [number, number];
  source: string;
}

export interface SignalPoint {
  t: number;
  v: number;
}

export interface SignalWindowData {
  channel: 'ppg' | 'hrv';
  label: string;
  unit: string;
  sampleRateHz: number;
  windowSeconds: WindowSeconds;
  raw: SignalPoint[];
  baseline: SignalPoint[];
  processed: SignalPoint[];
  analyzed: SignalPoint[];
  threshold?: number;
  simulated: boolean;
}

export interface SignalData {
  channel: SensorId;
  label: string;
  unit: string;
  sampleRateHz: number;
  windowSeconds: number;
  filtered: boolean;
  points: SignalPoint[];
  /** Optional richer payload for the observatory. Backends may return only points today. */
  raw?: SignalPoint[];
  baseline?: SignalPoint[];
  processed?: SignalPoint[];
  analyzed?: SignalPoint[];
  simulated?: boolean;
}

export interface TrendPoint {
  t: number;
  hr: number;
  hrv: number;
  spo2: number;
  temp: number;
  activity: number;
  risk: number;
}

export interface Anomaly {
  id: string;
  detectedAt: number;
  status: AnomalyStatus;
  score: number;
  reconstructionError: number;
  threshold: number;
  windowsFlagged: number;
  windowCount: number;
  witnesses: SensorId[];
  summary: string;
  simulated: boolean;
}

export interface WindowDetection {
  windowSeconds: WindowSeconds;
  reconstructionError: number;
  threshold: number;
  ratio: number;
  flagged: boolean;
  normalizedScore: number;
  model: string;
  updatedAt: number;
  history: Array<{ t: number; error: number }>;
}

export interface WitnessChannel {
  id: SensorId;
  label: string;
  status: ChannelStatus;
  score: number;
  threshold: number;
  supporting: boolean;
  similarity: number;
  note: string;
}

export interface MissionEvent {
  id: string;
  timestamp: number;
  title: string;
  detail: string;
  severity: Severity;
  category: 'sensor' | 'signal' | 'fusion' | 'witness' | 'alert' | 'system';
  astronautId?: string;
  astronautName?: string;
  channel?: SensorId | 'multi';
  status?: 'open' | 'monitoring' | 'validated' | 'resolved';
}

export interface ModelInfo {
  name: string;
  architecture: string;
  baselineWindows: number;
  thresholdRule: string;
  windowSet: WindowSeconds[];
  version: string;
  inferenceMs: number;
  simulated: boolean;
}

export interface StreamHealth {
  sampleRateHz: number;
  latencyMs: number;
  packetLossPct: number;
  bufferPct: number;
  channelsOnline: number;
  channelsTotal: number;
  batteryPct: number;
  link: 'nominal' | 'degraded' | 'offline';
}

export interface FusionResult {
  flaggedWindows: WindowSeconds[];
  flaggedCount: number;
  requiredCount: number;
  rule: string;
  alert: boolean;
  status: AnomalyStatus;
  witnesses: SensorId[];
}

export interface TelemetrySnapshot {
  mode: DataMode;
  scenario: DemoScenario;
  simTime: number;
  metSeconds: number;
  lastUpdate: number;
  paused: boolean;
  astronaut: Astronaut;
  mission: Mission;
  sensors: SensorReading[];
  vitals: {
    hr: number;
    hrv: number;
    spo2: number;
    temp: number;
    activity: number;
    sleep: number;
    activityLabel: string;
  };
  history: TrendPoint[];
  signal: {
    ppg: SignalPoint[];
    ecg: SignalPoint[];
    /** Beat-to-beat R-R intervals in milliseconds (simulated). */
    rrIntervals: number[];
    hrvTrend: SignalPoint[];
    spo2Trend: SignalPoint[];
  };
  windows: WindowDetection[];
  anomaly: {
    score: number;
    status: AnomalyStatus;
    reconstructionError: number;
    threshold: number;
    flaggedWindows: number;
    history: Array<{ t: number; score: number; error: number; threshold: number }>;
    current: Anomaly | null;
    log: Anomaly[];
  };
  fusion: FusionResult;
  witnesses: WitnessChannel[];
  events: MissionEvent[];
  model: ModelInfo;
  health: StreamHealth;
}

export interface MissionOverviewPayload {
  astronaut: Astronaut;
  mission: Mission;
  sensors: SensorReading[];
  anomaly: Anomaly;
  health: StreamHealth;
}
